// Unmanaged memory is outside the GC heap limit, so only the memory limit stops it.
let blocks = System.Collections.Generic.List<nativeint>()
while true do
    let block = System.Runtime.InteropServices.Marshal.AllocHGlobal(16 <<< 20)
    System.Span<byte>(block.ToPointer(), 16 <<< 20).Fill 1uy
    blocks.Add block

// The GC heap is capped below the memory limit, so exhausting it throws OutOfMemoryException.
let arrays = System.Collections.Generic.List<byte[]>()
while true do
    arrays.Add(Array.create (16 <<< 20) 1uy)

