// Each 16 MiB binary stays referenced from the list, so memory grows until the limit.
// Copying 64 bytes 262144 times fills 16 MiB quickly; one byte at a time is 60 times slower.
@external(erlang, "binary", "copy")
fn copy(bytes: BitArray, times: Int) -> BitArray

fn grow(blocks: List(BitArray)) -> List(BitArray) {
  grow([copy(<<1:size(512)>>, 262_144), ..blocks])
}

pub fn main() {
  grow([])
}

import bidict
import bigdecimal
import bitsandbobs/bitwise
import dijkstra
import gleam/deque
import gleam/dict
import gleam/int
import gleam/io
import gleam/order
import gleam/regexp
import gleam/yielder
import gleam_community/maths
import gleamy/priority_queue
import glearray
import ieee_float
import iv
import stdin
import trie

pub fn main() {
  let assert Ok(2) = bidict.from_list([#(1, 2)]) |> bidict.get_a(1)
  let assert Ok(half) = bigdecimal.from_string("1.5")
  let assert Ok(three) = bigdecimal.from_string("3")
  let assert order.Eq = bigdecimal.compare(bigdecimal.add(half, half), three)
  let assert <<6>> = bitwise.and(<<7>>, <<14>>)
  let edges = fn(node) {
    case node {
      1 -> dict.from_list([#(2, 1), #(3, 5)])
      2 -> dict.from_list([#(3, 1)])
      _ -> dict.new()
    }
  }
  let assert #([1, 2, 3], 2) =
    dijkstra.dijkstra(edges, 1) |> dijkstra.shortest_path(3)
  let assert 6 = maths.lcm(2, 3)
  let assert Ok(#(1, _)) = deque.from_list([1, 2]) |> deque.pop_front
  let assert Ok(pattern) = regexp.from_string("b+")
  let assert [regexp.Match(content: "bbb", ..)] = regexp.scan(pattern, "abbbc")
  let assert Ok(#(1, _)) =
    priority_queue.from_list([3, 1, 2], int.compare) |> priority_queue.pop
  let assert Ok(20) = glearray.from_list([10, 20]) |> glearray.get(1)
  let assert Ok(1.5) =
    ieee_float.finite(1.5)
    |> ieee_float.to_bytes_64_le
    |> ieee_float.from_bytes_64_le
    |> ieee_float.to_finite
  let assert Ok(30) = iv.from_list([10, 20, 30]) |> iv.get(2)
  let assert Ok(1) =
    trie.new() |> trie.insert(at: [1, 2], value: 1) |> trie.get(at: [1, 2])
  // Building the yielder reads nothing; this fixture also runs as an interactor, whose stdin stays open.
  let assert [] = stdin.read_lines() |> yielder.take(0) |> yielder.to_list
  io.println(int.to_string(1 + 2))
}

