import gleam/int
import gleam/io
import gleam/string
import gleam/yielder
import stdin

// Erlang writes standard output without buffering, so each question is out before the answer is read.
pub fn main() {
  ask(stdin.read_lines(), 10)
}

fn ask(lines: yielder.Yielder(String), n: Int) -> Nil {
  case n < 12 {
    False -> Nil
    True -> {
      io.println(int.to_string(n))
      let assert yielder.Next(line, rest) = yielder.step(lines)
      let assert Ok(x) = int.parse(string.trim(line))
      let assert True = x == 2 * n
      ask(rest, n + 1)
    }
  }
}

import gleam/int
import gleam/io
import gleam/string
import gleam/yielder
import stdin

// The yielder reads a line only when the next one is needed, so each answer goes out before the next question.
pub fn main() {
  stdin.read_lines()
  |> yielder.take(2)
  |> yielder.each(fn(line) {
    let assert Ok(n) = int.parse(string.trim(line))
    io.println(int.to_string(2 * n))
  })
}

import gleam/dynamic.{type Dynamic}
import gleam/io
import gleam/list

// A submission gets no arguments; judge code gets its files after -extra, the test input first.
@external(erlang, "init", "get_plain_arguments")
fn plain_arguments() -> List(Dynamic)

@external(erlang, "unicode", "characters_to_binary")
fn to_string(characters: Dynamic) -> String

@external(erlang, "file", "read_file")
fn read_file(path: String) -> Result(BitArray, Dynamic)

pub fn main() {
  case list.map(plain_arguments(), to_string) {
    [] -> Nil
    [input, ..] -> {
      let assert "/box/test-input" = input
      let assert Ok(_) = read_file(input)
      Nil
    }
  }
  io.println("3")
}

import gleam/io

// Not a tail call: every level waits for the sum below it, so 10^6 frames are live at once.
fn sum_to(n: Int) -> Int {
  case n {
    0 -> 0
    _ -> n + sum_to(n - 1)
  }
}

pub fn main() {
  let assert 500_000_500_000 = sum_to(1_000_000)
  io.println("3")
}

