import Minilib.Encoding.Base64;
import Minilib.Math.BigInt;
import Minilib.Monad.State;
import Minilib.Random.XorShift;
import Minilib.Text.Hex;
import Minilib.Text.SimpleParser;
import Minilib.Text.StringEx;
import Minilib.Trait.Rng;
import Random;
import RingBuffer;
import Time;

// Uses each library but minilib-json, minilib-xml and minilib-app, which compile slowly and have fixtures of their own.
// It reads no input: it also runs as an interactor, whose standard input stays open.
check : String -> Bool -> IO ();
check = |name, ok| assert(|_| name, ok);

main : IO ();
main = (
    check("binary-heap", [3, 1, 2].to_iter.fold(MinBinaryHeap::empty, BinaryHeap::push).get_top == some(1));;
    check("bool-array", BoolArray::fill(8, false).set(3, true).@(3));;
    check("cp-library", UnionFind::create(3).unite(0, 1).is_united(0, 1).@1);;
    check("character", Character::is_digit('7'));;
    check("gmp-fix", (MPZ::mpz(6) * MPZ::mpz(7)).to_string == "42");;
    check("hash", Hash::combine_hash(1_U64, 2_U64) == Hash::combine_hash(1_U64, 2_U64));;
    check("hashmap", HashMap::empty(0).HashMap::insert(1, 2).HashMap::find(1) == some(2));;
    check("hashset", HashSet::empty(0).HashSet::insert(3).HashSet::contains(3));;
    check("math", Math::floor(2.5) == 2.0);;
    check("minilib-collection", Deque::empty(0).push_back(1).push_back(2).get_front == some(1));;
    check("minilib-comonad", Minilib.Comonad.Store::store((1, |p| p * 3)).peek(2) == 6);;
    check("minilib-crypto", Minilib.Crypto.SHA256::digest("abc".get_bytes.pop_back).@size == 32);;
    check("minilib-binary", base64_encode("abc".get_bytes.pop_back) == "YWJj" && to_string_hex(255_U8) == "ff");;
    check("minilib-math", (BigInt::from_I64(3) * BigInt::from_I64(4)).to_string == "12");;
    check("minilib-monad", run_state(1, Minilib.Monad.State::state(|s| (s + 1, s * 2))) == (2, 2));;
    let xor_shift = XorShift::init_by_seed(1_U64);
    check("minilib-random", xor_shift.rng_U64.@data.@1 == xor_shift.rng_U64.@data.@1);;
    check("minilib-text", eval_parser_str("42", match_integer) == ok(42));;
    check("minilib-common", Minilib.Text.StringEx::to_upper("abc") == "ABC");;
    check("random", Random::init_by_seed(1_U64).generate_U64.@1 == Random::init_by_seed(1_U64).generate_U64.@1);;
    check("ring-buffer", RingBuffer::create([1, 2]).push_back(3).get_back == some(3));;
    check("time", (*Time::get_now).@sec > 0);;
    println("3")
);

module Main;

import Minilib.Encoding.Json;
import Minilib.Encoding.Json.JsonDecoder;
import Minilib.Encoding.Json.JsonEncoder;

// A program that uses minilib-json takes about 8 s to compile, so the other libraries are in fixtures of their own.
main : IO ();
main = (
    assert(|_| "minilib-json", encode(JsonDecoder::decode("[1,2]").as_ok) == "[1,2]");;
    println("3")
);

module Main;

import Minilib.Encoding.Xml;
import Minilib.Encoding.Xml.XmlParser;

// A program that uses minilib-xml takes about 6 s to compile, so the other libraries are in fixtures of their own.
main : IO ();
main = (
    assert(|_| "minilib-xml", parse_element_from_string("<a>3</a>").is_ok);;
    println("3")
);

module Main;

import Minilib.App.Clap;

// A program that uses minilib-app takes about 8 s to compile, so the other libraries are in fixtures of their own.
// The arguments are given here: judge code gets files as its own.
main : IO ();
main = (
    let command = Command::new("judge").arg(Arg::new("n").long("n").takes_value);
    assert(|_| "minilib-app", command.get_matches_from(["judge", "--n", "3"]).as_ok.get_one("n") == some("3"));;
    println("3")
);

module Main;

main : IO ();
main = (
    assert(|_| "marker exists", (*read_file_string("marker").to_result).is_err);;
    write_file_string("marker", "x").try(exit_with_msg(1));;
    println("3")
);

module Main;

// Standard output goes to a pipe, which the C library buffers: flush each question before reading the answer.
main : IO ();
main = loop_m(10, |n| (
    if n == 12 { break_m $ () };
    println(n.to_string);;
    stdout.flush;;
    let line = *read_line(stdin).try(exit_with_msg(1));
    assert(|_| "wrong answer", from_string(line.strip_spaces) == ok(2 * n));;
    continue_m $ n + 1
));

module Main;

main : IO ();
main = loop_m(0, |i| (
    if i == 2 { break_m $ () };
    let line = *read_line(stdin).try(exit_with_msg(1));
    let n : I64 = from_string(line.strip_spaces).as_ok;
    println((2 * n).to_string);;
    stdout.flush;;
    continue_m $ i + 1
));

module Main;

// A submission gets no arguments; judge code gets its files, the test input first. get_args starts with the program.
read_test_input : Array String -> IO ();
read_test_input = |args| (
    if args.@size == 1 { pure() };
    assert(|_| "unexpected first argument", args.@(1) == "/box/test-input");;
    let _ = *read_file_string(args.@(1)).try(exit_with_msg(1));
    pure()
);

main : IO ();
main = (
    read_test_input(*get_args);;
    println("3")
);

module Main;

// Not a tail call: every level looks at the sum below it before adding to it, so 10^6 frames are live at once.
// (LLVM turns a plain n + sum_to(n - 1) into a loop.)
sum_to : I64 -> I64;
sum_to = |n| (
    if n == 0 { 0 } else {
        let below = sum_to(n - 1);
        if below < 0 { below } else { below + n }
    }
);

main : IO ();
main = (
    assert_eq(|_| "wrong sum", sum_to(1000000), 500000500000);;
    println("3")
);

